package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
	"unicode/utf8"
)

// invalidByte is a lone byte that is never valid UTF-8 on its own.
const invalidByte = "\xff"

// anotherInvalidByte renders identically under JSON replacement but is a
// different raw byte.
const anotherInvalidByte = "\xfe"

// replacementRune is a genuine U+FFFD code point: valid UTF-8, unlike the
// lone invalid bytes.
const replacementRune = string(rune(0xFFFD))

// hashEnvelope is the historical fingerprint envelope struct the legacy
// JSON fingerprint family was computed over. Production no longer names
// it — the single record field table (record_fields.go) defines the
// envelope now — but the tests keep it as an independent oracle: if the
// table-driven JSON encoder ever drifted from the historical
// encoding/json output, the comparisons against legacyJSONFingerprint
// would catch it.
type hashEnvelope struct {
	Org             string          `json:"org"`
	Seq             int             `json:"seq"`
	Kind            string          `json:"kind"`
	Change          *PolicyChange   `json:"change,omitempty"`
	Decision        *DecisionRecord `json:"decision,omitempty"`
	PrevFingerprint string          `json:"prev"`
}

// legacyJSONFingerprint is the exact fingerprint algorithm used before
// the raw-content integrity fix: encoding/json over the envelope. Tests
// use it to prove valid-UTF-8 records keep byte-identical fingerprints.
func legacyJSONFingerprint(r *AuditRecord) string {
	b, err := json.Marshal(&hashEnvelope{
		Org:             r.Org,
		Seq:             r.Seq,
		Kind:            r.Kind,
		Change:          r.Change,
		Decision:        r.Decision,
		PrevFingerprint: r.PrevFingerprint,
	})
	if err != nil {
		panic(err)
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// cloneExportedRecords deep-copies a record set so mutating any string
// field or roles/matched/policies slice in the copy never reaches the
// original. encoding/json cannot be used for this: it would "repair" the
// invalid bytes under test.
func cloneExportedRecords(in []AuditRecord) []AuditRecord {
	out := make([]AuditRecord, len(in))
	for i, r := range in {
		cp := r
		if r.Change != nil {
			c := *r.Change
			if r.Change.Policies != nil {
				c.Policies = append([]Policy(nil), r.Change.Policies...)
			}
			cp.Change = &c
		}
		if r.Decision != nil {
			d := *r.Decision
			if r.Decision.Request.Subject.Roles != nil {
				d.Request.Subject.Roles = append([]string(nil), r.Decision.Request.Subject.Roles...)
			}
			if r.Decision.Decision.Matched != nil {
				d.Decision.Matched = append([]string(nil), r.Decision.Decision.Matched...)
			}
			cp.Decision = &d
		}
		out[i] = cp
	}
	return out
}

// TestInvalidUTF8IsAcceptedAndPreservedByteForByte drives the live API
// with strings carrying invalid UTF-8 in every policy and request string
// reachable through the public surface. Acceptance must be unchanged, no
// byte may be deleted, replaced or normalized, and query/export/offline
// review must observe the exact submitted bytes.
func TestInvalidUTF8IsAcceptedAndPreservedByteForByte(t *testing.T) {
	s := NewStore()
	submitted := Policy{
		ID:      "策" + invalidByte + "略",
		Subject: "用" + invalidByte + "戶",
		Action:  "读" + invalidByte,
		Scope:   "org/a/资" + invalidByte + "料",
		Effect:  EffectAllow,
	}
	v, err := s.Publish("acme", 0, []Policy{submitted})
	if err != nil || v != 1 {
		t.Fatalf("publish with invalid UTF-8 = %d, %v; want accepted", v, err)
	}

	req := OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject: Subject{
			ID:    "用" + invalidByte + "戶",
			Kind:  "外" + invalidByte + "部",
			Roles: []string{"角" + invalidByte + "色", "普通角色"},
		},
		Resource: Resource{ID: "资" + invalidByte + "源", Scope: submitted.Scope},
		Action:   submitted.Action,
	}
	d := s.Decide("acme", req)
	if !d.Allowed || d.Version != 1 || d.Reason != "matched allow policy" {
		t.Fatalf("decision on invalid-UTF-8 request = %+v", d)
	}
	if want := []string{submitted.ID}; !reflect.DeepEqual(d.Matched, want) {
		t.Fatalf("matched = %q, want byte-exact %q", d.Matched, want)
	}
	if !strings.Contains(d.Matched[0], invalidByte) {
		t.Fatal("invalid byte normalized out of matched policy id")
	}

	// A rollback republishes the invalid-byte content and records it.
	if rv, err := s.Rollback("acme", 1, 1); err != nil || rv != 2 {
		t.Fatalf("rollback = %d, %v", rv, err)
	}
	// A normal record and an invalid-byte record coexist in one export.
	if _, err := s.Publish("acme", 2, nil); err != nil {
		t.Fatal(err)
	}
	plain := s.Decide("acme", request("acme", "plain", "r1", "org/a", "read"))
	if plain.Allowed {
		t.Fatalf("plain request under empty version must deny: %+v", plain)
	}

	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit("acme", recs, cp); err != nil {
		t.Fatalf("export with invalid UTF-8 must verify: %v", err)
	}

	// The export is byte-for-byte the submitted content at every level.
	gotPolicy := recs[0].Change.Policies[0]
	if !reflect.DeepEqual(gotPolicy, submitted) {
		t.Fatalf("policy bytes = %+v, want %+v", gotPolicy, submitted)
	}
	gotReq := recs[1].Decision.Request
	if !reflect.DeepEqual(gotReq, req) {
		t.Fatalf("request bytes = %+v, want %+v", gotReq, req)
	}
	if !reflect.DeepEqual(recs[1].Decision.Decision, d) {
		t.Fatalf("decision bytes = %+v, want %+v", recs[1].Decision.Decision, d)
	}
	if !reflect.DeepEqual(recs[2].Change.Policies, []Policy{submitted}) {
		t.Fatal("rollback record lost the published raw bytes")
	}
	for _, haystack := range []string{
		gotPolicy.ID, gotPolicy.Subject, gotPolicy.Action, gotPolicy.Scope,
		gotReq.Subject.ID, gotReq.Subject.Kind, gotReq.Subject.Roles[0],
		gotReq.Resource.ID, gotReq.Resource.Scope, gotReq.Action,
	} {
		if !strings.Contains(haystack, invalidByte) {
			t.Fatalf("invalid byte was deleted or normalized in %q", haystack)
		}
	}

	// Paged queries return the same bytes.
	page, err := s.AuditQuery("acme", 1, 1, "", "")
	if err != nil {
		t.Fatal(err)
	}
	queried := append([]AuditRecord(nil), page.Records...)
	for page.Next != 0 {
		page, err = s.AuditPage(page.Checkpoint, page.Next, 1, "", "")
		if err != nil {
			t.Fatal(err)
		}
		queried = append(queried, page.Records...)
	}
	if !reflect.DeepEqual(queried, recs) {
		t.Fatal("paged query bytes differ from the export bytes")
	}

	// Offline review recomputes from the raw request and recorded version.
	review, err := RecheckDecisionOffline("acme", recs, cp, 2)
	if err != nil {
		t.Fatalf("offline review: %v", err)
	}
	if !review.Consistent || !reflect.DeepEqual(review.Original, d) ||
		!reflect.DeepEqual(review.Recomputed, d) {
		t.Fatalf("offline review = %+v, want consistent with %+v", review, d)
	}
	if !strings.Contains(review.Recomputed.Matched[0], invalidByte) {
		t.Fatal("offline review normalized the matched policy id")
	}

	// An organization whose name itself carries invalid bytes: genesis
	// checkpoint, isolation and offline review all still work.
	weirdOrg := "组" + invalidByte + "织"
	if _, err := s.Publish(weirdOrg, 0, []Policy{submitted}); err != nil {
		t.Fatalf("publish into invalid-UTF-8 org: %v", err)
	}
	wreq := req
	wreq.SubjectOrg = weirdOrg
	wreq.ResourceOrg = weirdOrg
	if d := s.Decide(weirdOrg, wreq); !d.Allowed {
		t.Fatalf("decision inside invalid-UTF-8 org = %+v", d)
	}
	wrecs, wcp, err := s.AuditExport(weirdOrg, 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit(weirdOrg, wrecs, wcp); err != nil {
		t.Fatalf("invalid-UTF-8 org chain: %v", err)
	}
	if wr, err := RecheckDecisionOffline(weirdOrg, wrecs, wcp, 2); err != nil || !wr.Consistent {
		t.Fatalf("invalid-UTF-8 org offline review = %+v, %v", wr, err)
	}
	// The sequence-0 root checkpoint is the genesis for that org too.
	empty, emptyCP, err := s.AuditExport(weirdOrg+"-none", 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit(weirdOrg+"-none", empty, emptyCP); err != nil {
		t.Fatalf("genesis checkpoint: %v", err)
	}
}

// TestInvalidBytesFingerprintBuildsChainOfMixedRecords checks ordinary
// and invalid-byte records chaining together: ordinary records keep the
// legacy JSON fingerprint, the invalid-byte record verifies and is pinned
// by the checkpoint, and tampering either family fails with
// ErrInvalidRange.
func TestInvalidBytesFingerprintBuildsChainOfMixedRecords(t *testing.T) {
	s := NewStore()
	s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	s.Publish("acme", 1, []Policy{{
		ID:      "策" + invalidByte + "略",
		Subject: "用" + invalidByte + "戶",
		Action:  "read",
		Scope:   "org/a",
		Effect:  EffectAllow,
	}})
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit("acme", recs, cp); err != nil {
		t.Fatalf("mixed chain: %v", err)
	}
	if got := fingerprintFor(&recs[0]); got != legacyJSONFingerprint(&recs[0]) {
		t.Fatal("valid-UTF-8 record changed fingerprint family")
	}
	if got := fingerprintFor(&recs[1]); got != legacyJSONFingerprint(&recs[1]) {
		t.Fatal("valid-UTF-8 decision changed fingerprint family")
	}
	if got := fingerprintFor(&recs[2]); got == legacyJSONFingerprint(&recs[2]) {
		t.Fatal("invalid-byte record still uses the JSON fingerprint")
	}
	if recs[2].Fingerprint != cp.Fingerprint {
		t.Fatal("checkpoint does not pin the raw-encoded final record")
	}
	bad := cloneExportedRecords(recs)
	bad[2].Change.Policies[0].ID = strings.Replace(bad[2].Change.Policies[0].ID, invalidByte, anotherInvalidByte, 1)
	if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("tampered invalid-byte record err = %v, want ErrInvalidRange", err)
	}
	bad = cloneExportedRecords(recs)
	bad[0].Change.Policies[0].ID = "p2"
	if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("tampered ordinary record err = %v, want ErrInvalidRange", err)
	}
}

// buildInvalidByteChain constructs a chain where every fingerprinted
// string field can be probed. Record 1 is a policy change, record 2 the
// reviewed decision with an invalid byte embedded between legal Chinese
// in every nested field and list, record 3 a decision after the target.
func buildInvalidByteChain(t *testing.T) (string, []AuditRecord, Checkpoint) {
	t.Helper()
	org := "组" + invalidByte + "织"
	subjectID := "身" + invalidByte + "份"
	action := "动" + invalidByte + "作"
	scope := "范" + invalidByte + "围"
	p1 := Policy{
		ID:      "策" + invalidByte + "id",
		Subject: subjectID,
		Action:  action,
		Scope:   scope,
		Effect:  EffectAllow,
	}
	p2 := Policy{
		ID:      "命" + invalidByte + "中二",
		Subject: subjectID,
		Action:  action,
		Scope:   scope,
		Effect:  EffectAllow,
	}
	prev := genesisFingerprint(org)
	rec1 := syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
		Version: 1, Policies: []Policy{p1, p2},
	}, nil, prev)
	prev = rec1.Fingerprint
	rec2 := syntheticRecord(org, 2, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg:  org,
			ResourceOrg: org,
			Subject: Subject{
				ID:    subjectID, // invalid byte between legal Chinese
				Kind:  "类" + invalidByte + "型",
				Roles: []string{"角" + invalidByte + "色", "正常角色"},
			},
			Resource: Resource{ID: "资" + invalidByte + "源", Scope: scope},
			Action:   action,
		},
		Decision: Decision{
			Allowed: true,
			Reason:  "理" + invalidByte + "由",
			Matched: []string{p2.ID, p1.ID}, // sorted by raw bytes
			Version: 1,
		},
	}, prev)
	prev = rec2.Fingerprint
	rec3 := syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg:  org,
			ResourceOrg: org,
			Subject:     Subject{ID: "尾" + invalidByte + "随"},
			Resource:    Resource{ID: "later", Scope: "org/a"},
			Action:      "read",
		},
		Decision: Decision{Allowed: false, Reason: "no matching allow policy", Version: 1},
	}, prev)
	recs := []AuditRecord{rec1, rec2, rec3}
	cp := Checkpoint{Org: org, EndSeq: 3, Fingerprint: rec3.Fingerprint}
	if err := VerifyAudit(org, recs, cp); err != nil {
		t.Fatalf("test fixture must verify: %v", err)
	}
	return org, recs, cp
}

// TestTamperedInvalidBytesRejectedEverywhere replaces the lone 0xFF in
// every protected field with either 0xFE (the same display after JSON
// replacement) or a genuine U+FFFD. VerifyAudit must fail with
// ErrInvalidRange and offline review must refuse before returning any
// conclusion, including when the damage is after the target decision.
func TestTamperedInvalidBytesRejectedEverywhere(t *testing.T) {
	org, good, cp := buildInvalidByteChain(t)

	// Document the root cause: JSON renders both raw bytes identically.
	j1, _ := json.Marshal("身" + invalidByte + "份")
	j2, _ := json.Marshal("身" + anotherInvalidByte + "份")
	if !bytes.Equal(j1, j2) {
		t.Fatalf("test premise broken: JSON differs: %s vs %s", j1, j2)
	}

	mutators := []struct {
		name string
		fn   func([]AuditRecord, string)
	}{
		{"header org", func(r []AuditRecord, repl string) {
			r[0].Org = strings.Replace(r[0].Org, invalidByte, repl, 1)
		}},
		{"record kind", func(r []AuditRecord, repl string) {
			r[1].Kind += repl
		}},
		{"policy id", func(r []AuditRecord, repl string) {
			p := &r[0].Change.Policies[0]
			p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
		}},
		{"policy subject", func(r []AuditRecord, repl string) {
			p := &r[0].Change.Policies[0]
			p.Subject = strings.Replace(p.Subject, invalidByte, repl, 1)
		}},
		{"policy action", func(r []AuditRecord, repl string) {
			p := &r[0].Change.Policies[0]
			p.Action = strings.Replace(p.Action, invalidByte, repl, 1)
		}},
		{"policy scope", func(r []AuditRecord, repl string) {
			p := &r[0].Change.Policies[0]
			p.Scope = strings.Replace(p.Scope, invalidByte, repl, 1)
		}},
		{"policy effect", func(r []AuditRecord, repl string) {
			p := &r[0].Change.Policies[0]
			p.Effect = Effect(string(p.Effect) + repl)
		}},
		{"second policy in list", func(r []AuditRecord, repl string) {
			p := &r[0].Change.Policies[1]
			p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
		}},
		{"subject org", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.SubjectOrg = strings.Replace(r[1].Decision.Request.SubjectOrg, invalidByte, repl, 1)
		}},
		{"resource org", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.ResourceOrg = strings.Replace(r[1].Decision.Request.ResourceOrg, invalidByte, repl, 1)
		}},
		{"subject id between chinese", func(r []AuditRecord, repl string) {
			id := &r[1].Decision.Request.Subject.ID
			*id = strings.Replace(*id, invalidByte, repl, 1)
		}},
		{"subject kind", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.Subject.Kind = strings.Replace(r[1].Decision.Request.Subject.Kind, invalidByte, repl, 1)
		}},
		{"first role in list", func(r []AuditRecord, repl string) {
			roles := r[1].Decision.Request.Subject.Roles
			roles[0] = strings.Replace(roles[0], invalidByte, repl, 1)
		}},
		{"second role in list", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.Subject.Roles[1] += repl
		}},
		{"resource id", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.Resource.ID = strings.Replace(r[1].Decision.Request.Resource.ID, invalidByte, repl, 1)
		}},
		{"resource scope", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.Resource.Scope = strings.Replace(r[1].Decision.Request.Resource.Scope, invalidByte, repl, 1)
		}},
		{"request action", func(r []AuditRecord, repl string) {
			r[1].Decision.Request.Action = strings.Replace(r[1].Decision.Request.Action, invalidByte, repl, 1)
		}},
		{"decision reason", func(r []AuditRecord, repl string) {
			r[1].Decision.Decision.Reason = strings.Replace(r[1].Decision.Decision.Reason, invalidByte, repl, 1)
		}},
		{"first matched policy", func(r []AuditRecord, repl string) {
			m := r[1].Decision.Decision.Matched
			m[0] = strings.Replace(m[0], invalidByte, repl, 1)
		}},
		{"second matched policy", func(r []AuditRecord, repl string) {
			m := r[1].Decision.Decision.Matched
			m[1] = strings.Replace(m[1], invalidByte, repl, 1)
		}},
		{"record after target", func(r []AuditRecord, repl string) {
			id := &r[2].Decision.Request.Subject.ID
			*id = strings.Replace(*id, invalidByte, repl, 1)
		}},
	}

	for _, repl := range []string{anotherInvalidByte, replacementRune} {
		for _, m := range mutators {
			recs := cloneExportedRecords(good)
			m.fn(recs, repl)
			name := m.name + "/repl=" + replacementLabel(repl)
			if err := VerifyAudit(org, recs, cp); !errors.Is(err, ErrInvalidRange) {
				t.Fatalf("%s: VerifyAudit err = %v, want ErrInvalidRange", name, err)
			}
			// Offline review must reject first: never a successful or
			// "consistent" conclusion over tampered material.
			if got, err := RecheckDecisionOffline(org, recs, cp, 2); !errors.Is(err, ErrInvalidRange) {
				t.Fatalf("%s: RecheckDecisionOffline err = %v, review = %+v, want ErrInvalidRange", name, err, got)
			}
		}
	}
}

// replacementLabel names a substitution without relying on rendered
// output, which displays both cases as a replacement character.
func replacementLabel(s string) string {
	switch s {
	case anotherInvalidByte:
		return "0xFE"
	case replacementRune:
		return "U+FFFD"
	default:
		return "?"
	}
}

// TestReplacementRuneIsGenuineContentToo separates three byte-different
// strings that displays may conflate: a lone 0xFF, a lone 0xFE, and a
// real U+FFFD rune. A record genuinely containing U+FFFD is valid UTF-8,
// verifies and keeps the legacy fingerprint; substituting any one for
// another is a content change.
func TestReplacementRuneIsGenuineContentToo(t *testing.T) {
	s := NewStore()
	policies := []Policy{{
		ID:      "p-" + replacementRune + "-1",
		Subject: "用" + replacementRune + "戶",
		Action:  "read", Scope: "org/a", Effect: EffectAllow,
	}}
	s.Publish("acme", 0, policies)
	req := request("acme", "用"+replacementRune+"戶", "r1", "org/a", "read")
	d := s.Decide("acme", req)
	if !d.Allowed {
		t.Fatalf("request with genuine U+FFFD = %+v", d)
	}
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit("acme", recs, cp); err != nil {
		t.Fatalf("genuine U+FFFD must verify: %v", err)
	}
	if !utf8.ValidString(recs[0].Change.Policies[0].ID) {
		t.Fatal("genuine U+FFFD must remain valid UTF-8")
	}
	if fingerprintFor(&recs[0]) != legacyJSONFingerprint(&recs[0]) {
		t.Fatal("valid-UTF-8 U+FFFD record must keep the legacy JSON fingerprint")
	}
	if review, err := RecheckDecisionOffline("acme", recs, cp, 2); err != nil || !review.Consistent {
		t.Fatalf("genuine U+FFFD review = %+v, %v", review, err)
	}

	// Raw invalid bytes exported from the live API.
	raw := NewStore()
	raw.Publish("acme", 0, []Policy{{
		ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow,
	}})
	rawRecs, rawCP, err := raw.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit("acme", rawRecs, rawCP); err != nil {
		t.Fatalf("raw-byte record must verify: %v", err)
	}

	// Replace the raw byte with a genuine U+FFFD rune: content changed.
	tampered := cloneExportedRecords(rawRecs)
	tampered[0].Change.Policies[0].ID = "p" + replacementRune
	if err := VerifyAudit("acme", tampered, rawCP); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("raw 0xFF -> U+FFFD err = %v, want ErrInvalidRange", err)
	}

	// The reverse substitution is also a change: the valid-UTF-8 record's
	// real U+FFFD replaced by a lone 0xFF.
	back := cloneExportedRecords(recs)
	back[0].Change.Policies[0].ID = "p-" + invalidByte + "-1"
	if err := VerifyAudit("acme", back, cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("U+FFFD -> raw 0xFF err = %v, want ErrInvalidRange", err)
	}
}

// TestLegacyFingerprintsUnchangedForValidUTF8 proves byte-identical
// fingerprints for valid UTF-8 across policy changes, rollbacks,
// decisions, nil-vs-empty lists, and strings full of characters JSON
// escapes specially: Chinese, quotes, backslashes, control characters,
// angle/ampersand and a genuine replacement rune.
func TestLegacyFingerprintsUnchangedForValidUTF8(t *testing.T) {
	org := "acme"
	tricky := []Policy{{
		ID:        "p\"1\\中\t\n\r<>&" + replacementRune,
		Subject:   "主\"体\\",
		Action:    "a\tb\nc",
		Scope:     "org/中/区",
		Effect:    EffectAllow,
		Recursive: true,
	}}
	prev := genesisFingerprint(org)
	records := []AuditRecord{
		syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
			Version: 1, Policies: tricky,
		}, nil, prev),
	}
	prev = records[0].Fingerprint
	// Rollback carrying a nil policy set.
	records = append(records, syntheticRecord(org, 2, AuditPolicyChange, &PolicyChange{
		Version: 2, Policies: nil, SourceVersion: 1, RolledBack: true,
	}, nil, prev))
	prev = records[1].Fingerprint
	// Decision with nil roles and nil matched lists.
	records = append(records, syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg:  org,
			ResourceOrg: org,
			Subject:     Subject{ID: "身\"份\\中"},
			Resource:    Resource{ID: "r\"1", Scope: "org/中/区"},
			Action:      "a\tb",
		},
		Decision: Decision{Allowed: true, Reason: "理\"由\n中", Version: 2},
	}, prev))
	prev = records[2].Fingerprint
	// Decision with explicitly empty (non-nil) lists.
	records = append(records, syntheticRecord(org, 4, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg:  org,
			ResourceOrg: org,
			Subject:     Subject{ID: "u2", Roles: []string{}},
			Resource:    Resource{ID: "r2", Scope: "org/a"},
			Action:      "read",
		},
		Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: []string{}, Version: 2},
	}, prev))

	for i := range records {
		r := &records[i]
		if got := fingerprintFor(r); got != legacyJSONFingerprint(r) {
			t.Fatalf("record %d fingerprint drifted from the legacy JSON encoding", r.Seq)
		}
	}
	cp := Checkpoint{Org: org, EndSeq: len(records), Fingerprint: records[len(records)-1].Fingerprint}
	if err := VerifyAudit(org, records, cp); err != nil {
		t.Fatalf("legacy-compatible chain must verify: %v", err)
	}

	// Sanity: an invalid byte makes the same shape leave the JSON family.
	raw := syntheticRecord(org, 5, AuditDecision, nil, &DecisionRecord{
		Request:  request(org, "u"+invalidByte, "r1", "org/a", "read"),
		Decision: Decision{Allowed: false, Reason: "x", Version: 2},
	}, cp.Fingerprint)
	if fingerprintFor(&raw) == legacyJSONFingerprint(&raw) {
		t.Fatal("invalid-byte envelope unexpectedly shares the JSON fingerprint")
	}
}

// This file is the regression guard pinning down that the two access entry
// points use two different authorization bases:
//
//   - Access (the demo core) decides solely from the subject's carried
//     roles: "owner" or "<scope>:<action>" grants. It never consults a
//     published policy, has no policy store, and reports the granting role
//     name in Decision.Matched with Version always 0.
//   - Store.Decide decides solely from the decision organization's currently
//     published policies. Subject roles, even "owner", never participate;
//     Decision.Matched carries policy identifiers and Version is the
//     published version actually evaluated (0 only when none was used).
//
// The two legitimately disagree about the same enabled service principal
// reading the same ledger, so every assertion below compares the full
// explanation — allowed, reason, matched entries and version — never the
// boolean alone. All material is generated in-process; the suite needs only
// the Go standard library and runs offline.
package darksafe

import (
	"reflect"
	"testing"
)

// Fixture values shared with examples/org_decision: one enabled service
// principal reading one ledger in one organization.
const (
	basisOrg        = "acme factory"
	basisLedgerID   = "ledger-2026"
	basisScope      = "acme/factory/ledger"
	basisSubjectID  = "svc-audit-reader"
	basisAction     = "read"
	basisPolicyID   = "p-ledger-read-2026"
	basisOwnerRole  = "owner"
	basisScopedRole = basisScope + ":" + basisAction // acme/factory/ledger:read
)

// basisSubject builds the enabled service principal with the given roles.
// No argument means no roles at all.
func basisSubject(roles ...string) Subject {
	return Subject{ID: basisSubjectID, Kind: "service", Roles: roles}
}

func basisLedger() Resource { return Resource{ID: basisLedgerID, Scope: basisScope} }

// basisRequest builds a complete, envelope-valid organization request:
// subject organization, resource organization and decision organization all
// agree and every identifier and the action are present.
func basisRequest(roles ...string) OrgRequest {
	return OrgRequest{
		SubjectOrg:  basisOrg,
		ResourceOrg: basisOrg,
		Subject:     basisSubject(roles...),
		Resource:    basisLedger(),
		Action:      basisAction,
	}
}

// basisAllowPolicy is the one matching allow policy: this subject, this
// action and the ledger's exact scope, with no resource qualifier.
func basisAllowPolicy() Policy {
	return allowPolicy(basisPolicyID, basisSubjectID, basisAction, basisScope, false)
}

// wantDecision compares the complete explanation an entry point must
// preserve. Matched order is significant (policy hits are documented as
// sorted); a nil list and a non-nil empty list are the same explanation,
// namely "nothing matched".
func wantDecision(t *testing.T, got Decision, allowed bool, reason string, matched []string, version int, context string) {
	t.Helper()
	if got.Allowed != allowed {
		t.Fatalf("%s: allowed = %v, want %v; decision = %+v", context, got.Allowed, allowed, got)
	}
	if got.Reason != reason {
		t.Fatalf("%s: reason = %q, want %q; decision = %+v", context, got.Reason, reason, got)
	}
	if got.Version != version {
		t.Fatalf("%s: version = %d, want %d; decision = %+v", context, got.Version, version, got)
	}
	gotMatched := got.Matched
	if len(gotMatched) == 0 {
		gotMatched = nil
	}
	wantMatched := matched
	if len(wantMatched) == 0 {
		wantMatched = nil
	}
	if !reflect.DeepEqual(gotMatched, wantMatched) {
		t.Fatalf("%s: matched = %q, want %q; decision = %+v", context, gotMatched, wantMatched, got)
	}
}

// TestAccessAndDecideUseDifferentAuthorizationBases drives the same enabled
// principal and ledger through both entry points before any policy is
// published. Access allows on a role while Decide denies for lack of a
// published version: the divergence is expected, and the two sides'
// explanations must not be read as the same kind of grant.
func TestAccessAndDecideUseDifferentAuthorizationBases(t *testing.T) {
	cases := []struct {
		name  string
		roles []string
		grant string // the role that actually grants the Access read
	}{
		{name: "owner role", roles: []string{basisOwnerRole}, grant: basisOwnerRole},
		{name: "ledger scoped read role", roles: []string{basisScopedRole}, grant: basisScopedRole},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			subject := basisSubject(tc.roles...)

			// Access: the carried role is the whole authorization basis. The
			// matched entry is the role that actually granted the read, and
			// version 0 means Access never evaluates a published policy.
			access := Access(subject, basisLedger(), basisAction)
			wantDecision(t, access,
				true, "role grants "+basisAction+":"+basisScope,
				[]string{tc.grant}, 0, "Access with granting role")

			// Decide on a fresh store: the envelope is valid (all three
			// organizations agree, identifiers complete) and the very same
			// roles ride along in the request, but no policy has been
			// published. Roles cannot stand in for one, so the request is
			// denied, the reason names the missing published version, the
			// matched list is empty and no version was used.
			store := NewStore()
			decide := store.Decide(basisOrg, basisRequest(tc.roles...))
			wantDecision(t, decide,
				false, "organization has no published version",
				nil, 0, "Decide before first publish")

			// The two version-0 answers are not one shared record: Access
			// allowed carrying a role name, Decide denied with an empty hit
			// list. A role name must never be reported as an org policy hit.
			if len(decide.Matched) != 0 {
				t.Fatalf("unpublished Decide must have no matched entries, got %q", decide.Matched)
			}
			if reflect.DeepEqual(access.Matched, decide.Matched) {
				t.Fatalf("Access role hit %q must not be interpretable as a Decide policy hit", access.Matched)
			}
		})
	}
}

// TestVersionZeroIsNotAUniformDenyMarker makes the meaning of version 0
// explicit across both entry points: it says "no published policy was
// evaluated", nothing about allow versus deny.
func TestVersionZeroIsNotAUniformDenyMarker(t *testing.T) {
	// Version 0 with an allow: Access granted by the owner role.
	access := Access(basisSubject(basisOwnerRole), basisLedger(), basisAction)
	wantDecision(t, access, true, "role grants "+basisAction+":"+basisScope,
		[]string{basisOwnerRole}, 0, "Access allow is also version 0")

	// Version 0 with a denial: an envelope-valid request on an organization
	// that has never published.
	store := NewStore()
	unpublished := store.Decide(basisOrg, basisRequest(basisOwnerRole))
	wantDecision(t, unpublished, false, "organization has no published version",
		nil, 0, "Decide denial on an unpublished organization")

	// A denial produced *after* evaluating a published version reports that
	// version, not 0: the published empty policy set denies by default and
	// the result must be distinguishable from "nothing published yet".
	if v, err := store.Publish(basisOrg, 0, nil); err != nil || v != 1 {
		t.Fatalf("publish empty set = %d, %v; want 1, nil", v, err)
	}
	emptySet := store.Decide(basisOrg, basisRequest(basisOwnerRole))
	wantDecision(t, emptySet, false, "no matching allow policy",
		nil, 1, "Decide denial under the published empty set")
}

// TestAccessMatchedEntryIsTheGrantingRole pins which role appears in
// Decision.Matched: it is the role that actually granted the read, in the
// role list's iteration order, never a policy identifier.
func TestAccessMatchedEntryIsTheGrantingRole(t *testing.T) {
	// A non-granting role ahead of owner does not replace the hit.
	subject := basisSubject("billing:invoice", basisOwnerRole, basisScopedRole)
	access := Access(subject, basisLedger(), basisAction)
	wantDecision(t, access, true, "role grants "+basisAction+":"+basisScope,
		[]string{basisOwnerRole}, 0, "owner encountered first grants")

	// Without owner, the scope-qualified role is the granting entry even
	// amid unrelated roles.
	subject = basisSubject("admin", basisScopedRole, "auditor")
	access = Access(subject, basisLedger(), basisAction)
	wantDecision(t, access, true, "role grants "+basisAction+":"+basisScope,
		[]string{basisScopedRole}, 0, "scope role encountered first grants")

	// A write-scoped role does not grant the read, and the policy identifier
	// is unknown to Access: it can never surface as a role hit.
	subject = basisSubject(basisScope + ":write")
	access = Access(subject, basisLedger(), basisAction)
	wantDecision(t, access, false, "no role grants "+basisAction+":"+basisScope,
		nil, 0, "write role cannot grant read")
	for _, hit := range access.Matched {
		if hit == basisPolicyID {
			t.Fatalf("Access matched a policy identifier: %q", hit)
		}
	}
}

// TestAccessResultIsIndependentOfPublishedPolicies shows the demo entry
// point cannot start depending on published-policy state: identical Access
// inputs return byte-identical decisions before a store exists, on a
// unpublished store and after a matching allow policy is published.
func TestAccessResultIsIndependentOfPublishedPolicies(t *testing.T) {
	withRole := func() Decision {
		return Access(basisSubject(basisOwnerRole), basisLedger(), basisAction)
	}
	withoutRole := func() Decision {
		return Access(basisSubject(), basisLedger(), basisAction)
	}

	before := withRole()
	store := NewStore()
	midUnpublished := withRole()
	if _, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()}); err != nil {
		t.Fatal(err)
	}
	afterPublish := withRole()
	if !reflect.DeepEqual(before, midUnpublished) || !reflect.DeepEqual(before, afterPublish) {
		t.Fatalf("Access decision changed around policy publishing: %+v / %+v / %+v",
			before, midUnpublished, afterPublish)
	}

	// The role-less denial is just as stable, and publishing an allow does
	// not rescue it: Access has no path from a policy to an allow.
	denyBefore := withoutRole()
	denyAfter := withoutRole()
	wantDecision(t, denyBefore, false, "no role grants "+basisAction+":"+basisScope, nil, 0,
		"role-less Access denial")
	if !reflect.DeepEqual(denyBefore, denyAfter) {
		t.Fatalf("role-less Access changed after publish: %+v vs %+v", denyBefore, denyAfter)
	}
}

// TestDecideWithMatchingAllowPolicyIgnoresRoles covers the published-policy
// half of the divergence: with a matching allow policy published, removing
// every role leaves the organization decision allowed and fully explained
// by the policy and its published version, while the demo decision denies
// for lack of a granting role.
func TestDecideWithMatchingAllowPolicyIgnoresRoles(t *testing.T) {
	store := NewStore()
	version, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()})
	if err != nil || version != 1 {
		t.Fatalf("publish matching allow = %d, %v; want 1, nil", version, err)
	}

	// No roles at all: the policy alone carries the organization decision.
	decide := store.Decide(basisOrg, basisRequest())
	wantDecision(t, decide, true, "matched allow policy",
		[]string{basisPolicyID}, version, "Decide with all roles removed")

	// The same request through the demo core is denied precisely because no
	// role grants this read — the published policy is not a role.
	access := Access(basisSubject(), basisLedger(), basisAction)
	wantDecision(t, access, false, "no role grants "+basisAction+":"+basisScope,
		nil, 0, "Access denies the role-less read despite the published allow")

	// The policy identifier is the org side's hit; a role name is the demo
	// side's hit. The two matched entries name different authorization
	// records and must not be unified.
	if decide.Matched[0] == basisOwnerRole || access.Matched != nil {
		t.Fatalf("hit kinds conflated: decide matched %q, access matched %q",
			decide.Matched, access.Matched)
	}
}

// TestChangingRolesNeverChangesOrgDecision varies only the carried roles.
// As long as the request content and published policy are otherwise
// unchanged, the organization decision must be identical in every
// explanatory field — not just in whether it allows. Meanwhile the demo
// decision does vary with the roles, proving the inputs are meaningful.
func TestChangingRolesNeverChangesOrgDecision(t *testing.T) {
	store := NewStore()
	version, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()})
	if err != nil || version != 1 {
		t.Fatalf("publish matching allow = %d, %v; want 1, nil", version, err)
	}

	roleSets := [][]string{
		nil,
		{},
		{basisOwnerRole},
		{basisScopedRole},
		{basisOwnerRole, basisScopedRole},
		{basisScopedRole, basisOwnerRole},
		{"unrelated-role", "admin"},
		{basisScope + ":write"}, // a write role says nothing about the read
	}

	baseline := store.Decide(basisOrg, basisRequest(roleSets[0]...))
	wantDecision(t, baseline, true, "matched allow policy",
		[]string{basisPolicyID}, version, "baseline org decision")

	sawAccessAllow, sawAccessDeny := false, false
	for _, roles := range roleSets {
		context := "role variant " + describeRoles(roles)
		got := store.Decide(basisOrg, basisRequest(roles...))
		// Full-field pinning: allowed, reason, matched list (and order) and
		// version all stay constant as the roles change.
		if !reflect.DeepEqual(got, baseline) {
			t.Fatalf("%s: org decision changed from %+v to %+v", context, baseline, got)
		}
		if got.Allowed && (len(got.Matched) != 1 || got.Matched[0] != basisPolicyID) {
			t.Fatalf("%s: allow must be attributed to the policy, not roles: %+v", context, got)
		}

		access := Access(basisSubject(roles...), basisLedger(), basisAction)
		if access.Allowed {
			sawAccessAllow = true
			wantDecision(t, access, true, "role grants "+basisAction+":"+basisScope,
				rolesContainingGrant(roles), 0, context+" Access")
		} else {
			sawAccessDeny = true
			wantDecision(t, access, false, "no role grants "+basisAction+":"+basisScope,
				nil, 0, context+" Access")
		}
	}
	if !sawAccessAllow || !sawAccessDeny {
		t.Fatalf("role variants must move the demo decision both ways, saw allow=%v deny=%v",
			sawAccessAllow, sawAccessDeny)
	}
}

// describeRoles renders a role set for test failure messages.
func describeRoles(roles []string) string {
	if roles == nil {
		return "<nil>"
	}
	return "[" + joinRoles(roles) + "]"
}

func joinRoles(roles []string) string {
	out := ""
	for i, r := range roles {
		if i > 0 {
			out += ","
		}
		out += r
	}
	return out
}

// rolesContainingGrant returns the role that Access actually grants with,
// in iteration order, for an Access allow assertion.
func rolesContainingGrant(roles []string) []string {
	for _, r := range roles {
		if r == basisOwnerRole || r == basisScopedRole {
			return []string{r}
		}
	}
	return nil
}

// TestBothBasesRejectDisabledSubject pins the shared boundary: a disabled
// principal is denied on both sides with the same explicit reason, and
// neither an owner/scoped role nor a matching published allow policy can
// override the deactivation.
func TestBothBasesRejectDisabledSubject(t *testing.T) {
	store := NewStore()
	if _, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()}); err != nil {
		t.Fatal(err)
	}

	disabledSubject := basisSubject(basisOwnerRole, basisScopedRole)
	disabledSubject.Disabled = true

	access := Access(disabledSubject, basisLedger(), basisAction)
	wantDecision(t, access, false, "subject is disabled", nil, 0,
		"Access with disabled subject and granting roles")

	req := basisRequest(basisOwnerRole, basisScopedRole)
	req.Subject.Disabled = true
	decide := store.Decide(basisOrg, req)
	wantDecision(t, decide, false, "subject is disabled", nil, 0,
		"Decide with disabled subject and matching allow policy")
}

// TestOrganizationMismatchRejectsBeforePolicy pins the organization-level
// boundary: when the subject organization or resource organization differs
// from the decision organization, the request is rejected before any
// policy is consulted even though the allow policy matches — no policy hit,
// version 0, explicit organization-mismatch reason.
func TestOrganizationMismatchRejectsBeforePolicy(t *testing.T) {
	store := NewStore()
	if _, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()}); err != nil {
		t.Fatal(err)
	}

	mutations := map[string]func(*OrgRequest){
		"subject org mismatch":  func(r *OrgRequest) { r.SubjectOrg = "globex" },
		"resource org mismatch": func(r *OrgRequest) { r.ResourceOrg = "another factory" },
	}
	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			// Granting roles ride along: the envelope rejection must still
			// win, proving roles cannot cure an organization mismatch.
			req := basisRequest(basisOwnerRole, basisScopedRole)
			mutate(&req)
			got := store.Decide(basisOrg, req)
			wantDecision(t, got, false, "organization mismatch", nil, 0, name)
		})
	}

	// A request whose three organizations agree but carries no role still
	// passes the envelope and reaches the matching policy, confirming the
	// denials above are caused by the mismatch and not by anything else.
	aligned := store.Decide(basisOrg, basisRequest())
	wantDecision(t, aligned, true, "matched allow policy",
		[]string{basisPolicyID}, 1, "aligned organizations with no roles")
}

// TestEveryNonEmptyOrgDecideLeavesConsistentAuditRecord pins the audit
// boundary: every Decide with a non-empty decision organization — including
// the unpublished-version denial, the disabled-subject denial and both
// organization-mismatch denials — appends exactly one decision record whose
// stored conclusion is the decision that was returned and whose stored
// request is the request that was submitted.
func TestEveryNonEmptyOrgDecideLeavesConsistentAuditRecord(t *testing.T) {
	store := NewStore()

	noPolicy := store.Decide(basisOrg, basisRequest(basisOwnerRole)) // seq 1: denial, version 0
	wantDecision(t, noPolicy, false, "organization has no published version", nil, 0,
		"recorded unpublished denial")

	version, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()}) // seq 2
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	allowedNoRoles := store.Decide(basisOrg, basisRequest()) // seq 3: policy allow, version 1
	wantDecision(t, allowedNoRoles, true, "matched allow policy",
		[]string{basisPolicyID}, 1, "recorded allow")

	disabled := basisRequest(basisOwnerRole)
	disabled.Subject.Disabled = true
	disabledDenial := store.Decide(basisOrg, disabled) // seq 4: envelope denial
	wantDecision(t, disabledDenial, false, "subject is disabled", nil, 0, "recorded disabled denial")

	subjectMismatch := basisRequest(basisOwnerRole)
	subjectMismatch.SubjectOrg = "globex"
	mismatchDenial := store.Decide(basisOrg, subjectMismatch) // seq 5
	wantDecision(t, mismatchDenial, false, "organization mismatch", nil, 0,
		"recorded subject-org mismatch denial")

	resourceMismatch := basisRequest(basisScopedRole)
	resourceMismatch.ResourceOrg = "globex"
	resourceMismatchDenial := store.Decide(basisOrg, resourceMismatch) // seq 6
	wantDecision(t, resourceMismatchDenial, false, "organization mismatch", nil, 0,
		"recorded resource-org mismatch denial")

	records, cp, err := store.AuditExport(basisOrg, 0)
	if err != nil {
		t.Fatalf("AuditExport: %v", err)
	}
	if len(records) != 6 {
		t.Fatalf("chain length = %d, want 6 (one publish + five decisions)", len(records))
	}
	if err := VerifyAudit(basisOrg, records, cp); err != nil {
		t.Fatalf("decision chain must verify including every denial: %v", err)
	}

	for i := range records {
		if records[i].Seq != i+1 {
			t.Fatalf("record %d has seq %d, want gapless %d", i, records[i].Seq, i+1)
		}
	}

	// The single policy change sits at seq 2; every other record is a
	// decision carrying the exact returned conclusion and submitted request.
	change := records[1]
	if change.Kind != AuditPolicyChange || change.Change == nil || change.Change.Version != 1 {
		t.Fatalf("seq 2 must be the version-1 policy change: %+v", change)
	}

	type recorded struct {
		seq      int
		decision Decision
		request  OrgRequest
	}
	want := []recorded{
		{seq: 1, decision: noPolicy, request: basisRequest(basisOwnerRole)},
		{seq: 3, decision: allowedNoRoles, request: basisRequest()},
		{seq: 4, decision: disabledDenial, request: disabled},
		{seq: 5, decision: mismatchDenial, request: subjectMismatch},
		{seq: 6, decision: resourceMismatchDenial, request: resourceMismatch},
	}
	for _, w := range want {
		r := records[w.seq-1]
		if r.Kind != AuditDecision || r.Decision == nil {
			t.Fatalf("seq %d is not a decision record: %+v", w.seq, r)
		}
		// The recorded conclusion matches the returned one field for field,
		// matched list and version included.
		if !reflect.DeepEqual(r.Decision.Decision, w.decision) {
			t.Fatalf("seq %d recorded decision %+v != returned %+v",
				w.seq, r.Decision.Decision, w.decision)
		}
		if !reflect.DeepEqual(r.Decision.Request, w.request) {
			t.Fatalf("seq %d recorded request %+v != submitted %+v",
				w.seq, r.Decision.Request, w.request)
		}
		// The existing recheck entry point preserves the same explanation
		// from the recorded material alone — denials included.
		replayed, err := store.RecheckDecision(basisOrg, w.seq)
		if err != nil {
			t.Fatalf("RecheckDecision seq %d: %v", w.seq, err)
		}
		if !reflect.DeepEqual(replayed, w.decision) {
			t.Fatalf("seq %d recheck %+v != recorded decision %+v",
				w.seq, replayed, w.decision)
		}
	}

	// Concretely, the version-0 denial records really carry empty hit lists
	// and no version, while the allow record names the policy and version 1.
	if hits := records[0].Decision.Decision.Matched; len(hits) != 0 {
		t.Fatalf("unpublished-version record must have no hits, got %q", hits)
	}
	if records[4].Decision.Decision.Version != 0 || len(records[4].Decision.Decision.Matched) != 0 {
		t.Fatalf("mismatch record must be version 0 with no hits: %+v", records[4].Decision.Decision)
	}
	allowRec := records[2].Decision.Decision
	if !reflect.DeepEqual(allowRec.Matched, []string{basisPolicyID}) || allowRec.Version != 1 {
		t.Fatalf("allow record must name %q at version 1: %+v", basisPolicyID, allowRec)
	}
}

// TestAccessLeavesAuditChainAndPolicyVersionUntouched pins the demo entry
// point's other boundary: it has no store of its own and must not alter an
// organization's audit chain, current version or published content. This
// includes organizations that have never had any record at all.
func TestAccessLeavesAuditChainAndPolicyVersionUntouched(t *testing.T) {
	store := NewStore()
	version, err := store.Publish(basisOrg, 0, []Policy{basisAllowPolicy()})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}
	before, cpBefore, err := store.AuditExport(basisOrg, 0)
	if err != nil {
		t.Fatal(err)
	}
	if cpBefore.EndSeq != 1 {
		t.Fatalf("setup end seq = %d, want 1", cpBefore.EndSeq)
	}

	// Exercise Access every way this fixture allows — allow, role-less
	// denial and disabled denial — none of which even receives the store.
	Access(basisSubject(basisOwnerRole), basisLedger(), basisAction)
	Access(basisSubject(), basisLedger(), basisAction)
	disabled := basisSubject(basisOwnerRole)
	disabled.Disabled = true
	Access(disabled, basisLedger(), basisAction)

	after, cpAfter, err := store.AuditExport(basisOrg, 0)
	if err != nil {
		t.Fatal(err)
	}
	if cpAfter.EndSeq != cpBefore.EndSeq || cpAfter.Fingerprint != cpBefore.Fingerprint {
		t.Fatalf("Access moved the audit chain: checkpoint %+v -> %+v", cpBefore, cpAfter)
	}
	if !reflect.DeepEqual(after, before) {
		t.Fatalf("Access changed audit record content:\nbefore=%+v\nafter =%+v", before, after)
	}
	if got := store.CurrentVersion(basisOrg); got != version {
		t.Fatalf("current version = %d, want unchanged %d after Access", got, version)
	}
	published, err := store.Policies(basisOrg, version)
	if err != nil || !reflect.DeepEqual(published, []Policy{basisAllowPolicy()}) {
		t.Fatalf("published policies changed after Access: %+v, %v", published, err)
	}
	if err := VerifyAudit(basisOrg, after, cpAfter); err != nil {
		t.Fatalf("chain no longer verifies after Access: %v", err)
	}

	// An organization that only ever talked to Access has no chain and still
	// reports its empty genesis state.
	Access(basisSubject(basisOwnerRole), basisLedger(), basisAction)
	empty, emptyCP, err := store.AuditExport("factory that never decided", 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(empty) != 0 || emptyCP.EndSeq != 0 {
		t.Fatalf("Access created audit state for a fresh org: %+v, %+v", empty, emptyCP)
	}
	if err := VerifyAudit("factory that never decided", empty, emptyCP); err != nil {
		t.Fatalf("fresh-org genesis must verify: %v", err)
	}
}

// This file holds the shared core of single-decision review. The online
// Store.RecheckDecision and the store-free RecheckDecisionOffline acquire
// their material differently — one reads an organization's live history
// and version snapshots, the other a chain-validated export paired with its
// separately retained checkpoint — but once the recorded request and the
// version it actually used are in hand, both replay the exact same
// judgment. That judgment lives only here so the two entry points can never
// drift on version-zero handling, envelope rejection order, or how a
// historical policy set is evaluated.
package darksafe

// replayStatus reports whether replayRecordedDecision produced a decision
// or why the declared version could not be replayed.
type replayStatus int

const (
	// replayDecided means a Decision was recomputed.
	replayDecided replayStatus = iota
	// replayVersionAbsent means content for the declared version exists
	// nowhere in the reviewer's material.
	replayVersionAbsent
	// replayVersionAfterTarget means the version's content exists, but only
	// in a policy change record positioned after the reviewed decision.
	// Online material never yields this: live version snapshots carry no
	// position relative to audit records.
	replayVersionAfterTarget
)

// versionPolicies is one resolver verdict: either the detached full policy
// set of the requested version, or a status explaining why it is unusable.
type versionPolicies struct {
	policies []Policy
	status   replayStatus
}

// resolveVersionPolicies supplies the full content of a non-zero version
// named by a reviewed decision. Implementations are responsible for
// detaching the returned policies from any state or input material.
type resolveVersionPolicies func(version int) versionPolicies

// replayRecordedDecision re-judges a recorded request against the version
// the record declares it actually used. Later publishes or rollbacks are
// never substituted for that version.
//
// A version-0 record first replays the envelope rejections in their fixed
// order (missing organizations and identifiers, empty action, organization
// mismatch, illegal scope, disabled subject); a request that passes is the
// "organization has no published version" denial.
//
// For a non-zero record the version is resolved before any request rule is
// applied: a missing, or only-later, version is an error the caller turns
// into ErrVersionNotFound and must never be masked by an envelope denial,
// even for a disabled subject. Once the version is in hand, the same
// envelope checks run before policy evaluation, so a rejection reports
// version 0 with no matched policies regardless of what the version
// contains. Evaluation itself is the historical policy set only: deny
// overrides allow, matched identifiers are sorted, resource restrictions
// narrow rather than replace scope matching, and subject roles never stand
// in for an organization policy.
func replayRecordedDecision(org string, req OrgRequest, version int, resolve resolveVersionPolicies) (Decision, replayStatus) {
	if version == 0 {
		// The original evaluation used no published version: replay the
		// envelope rejections exactly, in their recorded order, then the
		// not-yet-published denial.
		if d, ok := checkRequest(org, req); !ok {
			return d, replayDecided
		}
		return Decision{Allowed: false, Reason: "organization has no published version"}, replayDecided
	}
	// Resolve the version first. A request the envelope would reject must
	// not turn a missing or later-only declared version into an ordinary
	// denial.
	resolved := resolve(version)
	if resolved.status != replayDecided {
		return Decision{}, resolved.status
	}
	// The version exists as claimed, but chain integrity does not imply the
	// request was admissible: re-run the same envelope checks the online
	// decision runs before any policy is consulted. A rejection here
	// evaluates no policies, hence version 0 and no matches, even when the
	// version holds a fully matching allow policy.
	if d, ok := checkRequest(org, req); !ok {
		return d, replayDecided
	}
	return evaluate(req, resolved.policies, version), replayDecided
}

// This file is the single definition of which fields a DecisionRecord
// carries for every audit-side treatment of decision content: the
// fingerprint's raw canonical encoder, the valid-UTF-8 test that chooses
// between the JSON and raw fingerprint families, the archive writer and
// reader, and the detaching copy that keeps stored records independent of
// caller slices. Each of those walks the one table below instead of naming
// the fields itself, so the fields and their order mean the same thing
// everywhere. Adding or changing a decision field here reaches
// fingerprinting, the UTF-8 decision, archiving, unarchiving and cloning at
// once; no audit path can keep a stale list of its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical decision field order — the two organization names, the subject,
// the resource, the action, then the decision itself — and the archive
// mirrors it field for field. Authorization itself (org.go) is intentionally
// not driven from this table: Roles participates here as a saved request
// field even though org policy evaluation never matches on it.
package darksafe

import "unicode/utf8"

// decisionFieldKind says how one DecisionRecord field participates in
// fingerprinting and archiving.
type decisionFieldKind int

const (
	// decisionFieldString is a string field written from its exact bytes by
	// both the fingerprint encoder and the archive.
	decisionFieldString decisionFieldKind = iota
	// decisionFieldStringList is a string slice whose nil-versus-empty
	// shape and element order are preserved explicitly by both encoders.
	decisionFieldStringList
	// decisionFieldBool is a boolean field. It has no UTF-8 representation,
	// so the valid-UTF-8 scan skips it while both encoders write it.
	decisionFieldBool
	// decisionFieldInt is a non-negative integer field (the policy version
	// the decision used). It has no UTF-8 representation either.
	decisionFieldInt
)

// decisionFieldSpec locates one DecisionRecord leaf field. The accessors
// used depend on the kind: string fields use getString/setString, list
// fields getList/setList, booleans getBool/setBool and integers
// getInt/setInt. A field appears in decisionFields exactly once, and that
// entry is the only place its struct member is named.
type decisionFieldSpec struct {
	kind decisionFieldKind
	// groupTag, when non-zero, is a nesting marker the fingerprint encoder
	// emits immediately before this field, opening the subject, resource or
	// decision group exactly where the historical encoding placed it. The
	// archive has no group markers and ignores this.
	groupTag  fingerprintTag
	getString func(*DecisionRecord) string
	setString func(*DecisionRecord, string)
	getList   func(*DecisionRecord) []string
	setList   func(*DecisionRecord, []string)
	getBool   func(*DecisionRecord) bool
	setBool   func(*DecisionRecord, bool)
	getInt    func(*DecisionRecord) int
	setInt    func(*DecisionRecord, int)
}

// decisionFields lists every DecisionRecord leaf field in fingerprint
// canonical order, which the archive reproduces exactly. The subject group
// opens at Subject.ID, the resource group at Resource.ID and the decision
// group at Decision.Allowed, matching the historical nesting markers.
var decisionFields = [...]decisionFieldSpec{
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.SubjectOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.SubjectOrg = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.ResourceOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.ResourceOrg = s },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagSubject,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.Kind },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.Kind = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Request.Subject.Roles },
		setList: func(d *DecisionRecord, l []string) { d.Request.Subject.Roles = l },
	},
	{
		kind:    decisionFieldBool,
		getBool: func(d *DecisionRecord) bool { return d.Request.Subject.Disabled },
		setBool: func(d *DecisionRecord, v bool) { d.Request.Subject.Disabled = v },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagResource,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.Scope },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.Scope = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Action },
		setString: func(d *DecisionRecord, s string) { d.Request.Action = s },
	},
	{
		kind:     decisionFieldBool,
		groupTag: tagDecision,
		getBool:  func(d *DecisionRecord) bool { return d.Decision.Allowed },
		setBool:  func(d *DecisionRecord, v bool) { d.Decision.Allowed = v },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Decision.Reason },
		setString: func(d *DecisionRecord, s string) { d.Decision.Reason = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Decision.Matched },
		setList: func(d *DecisionRecord, l []string) { d.Decision.Matched = l },
	},
	{
		kind:   decisionFieldInt,
		getInt: func(d *DecisionRecord) int { return d.Decision.Version },
		setInt: func(d *DecisionRecord, v int) { d.Decision.Version = v },
	},
}

// decisionRecordHasNonUTF8 reports whether any string or list element of d
// carries bytes that are not valid UTF-8. It ranges the single field table,
// so its idea of which decision strings the fingerprint protects can never
// diverge from the fields the encoders write. Boolean and integer fields
// cannot carry a raw byte and are skipped by kind rather than listed
// separately.
func decisionRecordHasNonUTF8(d *DecisionRecord) bool {
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			if !utf8.ValidString(f.getString(d)) {
				return true
			}
		case decisionFieldStringList:
			for _, s := range f.getList(d) {
				if !utf8.ValidString(s) {
					return true
				}
			}
		}
	}
	return false
}

// cloneDecisionLists detaches every string list field of src into dst,
// preserving each list's nil-versus-empty shape. It ranges the single field
// table, so a list field added to the record is detached here without this
// function changing.
func cloneDecisionLists(dst, src *DecisionRecord) {
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.kind == decisionFieldStringList {
			f.setList(dst, cloneStrings(f.getList(src)))
		}
	}
}

// Regression coverage for action names matched by their exact submitted
// bytes. One policy set can carry different effects for different actions
// of the same subject on the same resource; the request's action selects
// which policies may enter the hit list, and only the request's own raw
// action bytes do the selecting. An action that differs by case, by a
// surrounding space, or by one invalid byte is a DIFFERENT action: it must
// never borrow another action's allow policy, never fall under another
// action's deny policy, and never be normalized into another action before
// matching. The only invalid action is the empty string, and it is an
// envelope rejection decided before any policy is consulted.
//
// Every request here runs in one organization with an enabled subject and
// a legal scope, so each outcome is genuinely produced by action matching,
// not by an envelope rejection. The audit half pins that the raw action
// bytes and the full explanation survive the chain, an archive round trip
// and offline review: a decision recomputed from the saved material must
// come out identical, and records that differ only in the action must stay
// distinguishable rather than collapse onto one replaced character.
package darksafe

import (
	"bytes"
	"encoding/json"
	"errors"
	"reflect"
	"testing"
)

// Action fixture shared by this file: one enabled subject, one ledger, one
// legal scope, one organization.
const (
	actionOrg        = "acme"
	actionSubjectID  = "svc-ledger-writer"
	actionResourceID = "ledger-2026"
	actionScope      = "acme/factory/ledger"
)

// actionRequest builds a complete, envelope-valid organization request that
// varies only the action.
func actionRequest(action string) OrgRequest {
	return OrgRequest{
		SubjectOrg:  actionOrg,
		ResourceOrg: actionOrg,
		Subject:     Subject{ID: actionSubjectID, Kind: "service"}, // enabled
		Resource:    Resource{ID: actionResourceID, Scope: actionScope},
		Action:      action,
	}
}

// actionPolicy builds one policy for the shared subject, resource scope and
// the given action and effect.
func actionPolicy(id, action string, effect Effect) Policy {
	return Policy{ID: id, Subject: actionSubjectID, Action: action, Scope: actionScope, Effect: effect}
}

// wantActionDecision pins the complete explanation: verdict, reason, exact
// hit list (order significant) and the version actually evaluated.
func wantActionDecision(t *testing.T, got Decision, allowed bool, reason string, matched []string, version int, context string) {
	t.Helper()
	if got.Allowed != allowed {
		t.Fatalf("%s: allowed = %v, want %v; decision = %+v", context, got.Allowed, allowed, got)
	}
	if got.Reason != reason {
		t.Fatalf("%s: reason = %q, want %q; decision = %+v", context, got.Reason, reason, got)
	}
	if got.Version != version {
		t.Fatalf("%s: version = %d, want %d; decision = %+v", context, got.Version, version, got)
	}
	gotMatched := got.Matched
	if len(gotMatched) == 0 {
		gotMatched = nil
	}
	wantMatched := matched
	if len(wantMatched) == 0 {
		wantMatched = nil
	}
	if !reflect.DeepEqual(gotMatched, wantMatched) {
		t.Fatalf("%s: matched = %q, want %q; decision = %+v", context, gotMatched, wantMatched, got)
	}
}

// TestActionEffectsStayWithTheirOwnAction pins the basic isolation: one
// published version holds an allow for "read" and a deny for "write" for
// the same subject and resource. The read is allowed by its own policy
// alone, the write is denied by its own policy alone, and an action with no
// policy at all gets the default denial with an empty hit list. Neither
// action's policy may appear in the other action's explanation.
func TestActionEffectsStayWithTheirOwnAction(t *testing.T) {
	s := NewStore()
	version, err := s.Publish(actionOrg, 0, []Policy{
		actionPolicy("p-read-allow", "read", EffectAllow),
		actionPolicy("p-write-deny", "write", EffectDeny),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want version 1", version, err)
	}

	read := s.Decide(actionOrg, actionRequest("read"))
	wantActionDecision(t, read, true, "matched allow policy",
		[]string{"p-read-allow"}, 1, "read hits only its own allow")

	write := s.Decide(actionOrg, actionRequest("write"))
	wantActionDecision(t, write, false, "matched deny policy",
		[]string{"p-write-deny"}, 1, "write hits only its own deny")

	// No policy names "delete": the default denial applies, explained as the
	// missing allow with an empty hit list, still at the evaluated version.
	del := s.Decide(actionOrg, actionRequest("delete"))
	wantActionDecision(t, del, false, "no matching allow policy",
		nil, 1, "delete has no policy at all")

	// The hit lists are disjoint by construction of the matcher; pin it so a
	// future "close enough" action comparison cannot leak a policy across.
	for _, hit := range read.Matched {
		if hit == "p-write-deny" {
			t.Fatalf("read borrowed the write deny policy: %+v", read)
		}
	}
	for _, hit := range write.Matched {
		if hit == "p-read-allow" {
			t.Fatalf("write borrowed the read allow policy: %+v", write)
		}
	}
}

// TestDenyOverridesOnlyWithinTheMatchedAction pins the scope of deny
// precedence: a deny policy denies only requests whose action actually
// matches it. A deny published on "write" cannot override the allow on
// "read", while one action carrying both an allow and a deny is denied,
// with BOTH identifiers kept in the hit list, sorted ascending, at the
// version actually evaluated.
func TestDenyOverridesOnlyWithinTheMatchedAction(t *testing.T) {
	s := NewStore()
	// The commit pair is submitted deny-first so the ascending order of the
	// reported hit list is produced by the decision, not by the submission.
	version, err := s.Publish(actionOrg, 0, []Policy{
		actionPolicy("p-write-deny", "write", EffectDeny),
		actionPolicy("p-commit-deny", "commit", EffectDeny),
		actionPolicy("p-commit-allow", "commit", EffectAllow),
		actionPolicy("p-read-allow", "read", EffectAllow),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want version 1", version, err)
	}

	// Two deny policies exist in the same version, but neither matches the
	// read action: the read allow stands.
	read := s.Decide(actionOrg, actionRequest("read"))
	wantActionDecision(t, read, true, "matched allow policy",
		[]string{"p-read-allow"}, 1, "denies on other actions cannot override the read allow")

	// The commit action genuinely hits both effects: deny wins, and the
	// explanation keeps both identifiers in ascending order.
	commit := s.Decide(actionOrg, actionRequest("commit"))
	wantActionDecision(t, commit, false, "matched deny policy",
		[]string{"p-commit-allow", "p-commit-deny"}, 1, "allow and deny on the same action")

	// The write deny, evaluated alone, reports only its own identifier: the
	// commit pair does not leak into a request that cannot match it.
	write := s.Decide(actionOrg, actionRequest("write"))
	wantActionDecision(t, write, false, "matched deny policy",
		[]string{"p-write-deny"}, 1, "write deny stands alone")
}

// TestActionNamesDifferingByCaseOrSpaceStayDistinct pins that comparison is
// by exact bytes, not by any case folding or trimming: "read", "Read",
// " read" and "read " are four different actions, each matched only by its
// own policy, and an unlisted casing ("READ") falls to the default denial.
// All of them are non-empty, so every request reaches policy evaluation at
// the published version — none is rejected as an invalid request.
func TestActionNamesDifferingByCaseOrSpaceStayDistinct(t *testing.T) {
	variants := []struct {
		action   string
		policyID string
	}{
		{"read", "p-act-lower"},
		{"Read", "p-act-title"},
		{" read", "p-act-lead-space"},
		{"read ", "p-act-trail-space"},
	}
	policies := make([]Policy, 0, len(variants))
	for _, v := range variants {
		policies = append(policies, actionPolicy(v.policyID, v.action, EffectAllow))
	}
	s := NewStore()
	version, err := s.Publish(actionOrg, 0, policies)
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want version 1", version, err)
	}

	for _, v := range variants {
		got := s.Decide(actionOrg, actionRequest(v.action))
		wantActionDecision(t, got, true, "matched allow policy",
			[]string{v.policyID}, 1, "action "+showAction(v.action))
	}

	// A casing no policy carries is the default denial, not a folded match
	// on any of the four published variants.
	shout := s.Decide(actionOrg, actionRequest("READ"))
	wantActionDecision(t, shout, false, "no matching allow policy",
		nil, 1, "unlisted casing must not fold onto a published action")
}

// showAction renders an action for test failure messages, making
// surrounding spaces visible.
func showAction(action string) string {
	return "[" + action + "]"
}

// rawByteActions returns the three byte-different-but-display-conflated
// action names used by this file. The surrounding content is identical;
// exactly one middle position differs: a lone 0xFF byte, a lone 0xFE byte,
// and a genuine U+FFFD code point (valid UTF-8, three bytes EF BF BD).
func rawByteActions() (withFF, withFE, withReplacement string) {
	return "ledger-" + invalidByte + "-read",
		"ledger-" + anotherInvalidByte + "-read",
		"ledger-" + replacementRune + "-read"
}

// TestRawByteActionsStayDistinctInDecisions pins the authorization contract
// for actions carrying bytes that are not valid UTF-8: matching is against
// the request's raw action bytes, so a replacement of 0xFF with 0xFE (or
// with a genuine U+FFFD) can never make one action ride another action's
// allow or deny. None of the three is empty and none is invalid input —
// each reaches policy evaluation at the published version.
func TestRawByteActionsStayDistinctInDecisions(t *testing.T) {
	actFF, actFE, actFD := rawByteActions()

	// Document the premise this regression guards: Go string comparison
	// distinguishes the three actions, while encoding/json renders the two
	// lone invalid bytes identically. Any normalization or replacement at
	// the authorization boundary would collapse the first two.
	if actFF == actFE || actFF == actFD || actFE == actFD {
		t.Fatalf("test premise broken: actions must differ pairwise: %q %q %q", actFF, actFE, actFD)
	}
	jFF, _ := json.Marshal(actFF)
	jFE, _ := json.Marshal(actFE)
	if !bytes.Equal(jFF, jFE) {
		t.Fatalf("test premise broken: JSON renders the invalid bytes differently: %s vs %s", jFF, jFE)
	}

	s := NewStore()
	version, err := s.Publish(actionOrg, 0, []Policy{
		actionPolicy("p-act-ff-allow", actFF, EffectAllow),
		actionPolicy("p-act-fe-deny", actFE, EffectDeny),
		// No policy at all for the genuine-U+FFFD action.
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want version 1", version, err)
	}

	// The 0xFF action is allowed by its own policy alone, at the published
	// version: a non-empty raw-byte action is a valid request, never an
	// envelope rejection.
	allowFF := s.Decide(actionOrg, actionRequest(actFF))
	wantActionDecision(t, allowFF, true, "matched allow policy",
		[]string{"p-act-ff-allow"}, 1, "0xFF action hits its own allow")

	// The 0xFE action is denied by ITS OWN deny policy. The 0xFF action's
	// allow must not travel with it, and the explanation is the policy-deny
	// reason rather than the default denial.
	denyFE := s.Decide(actionOrg, actionRequest(actFE))
	wantActionDecision(t, denyFE, false, "matched deny policy",
		[]string{"p-act-fe-deny"}, 1, "0xFE action hits only its own deny")

	// The genuine-U+FFFD action has no policy: the default denial with an
	// empty hit list. Neither look-alike action's policy may be its basis.
	noPolicyFD := s.Decide(actionOrg, actionRequest(actFD))
	wantActionDecision(t, noPolicyFD, false, "no matching allow policy",
		nil, 1, "U+FFFD action has no policy at all")

	// The three explanations are pairwise distinguishable: an allow, a
	// policy-driven deny, and a no-authorization default deny.
	reasons := []string{allowFF.Reason, denyFE.Reason, noPolicyFD.Reason}
	for i := 0; i < len(reasons); i++ {
		for j := i + 1; j < len(reasons); j++ {
			if reasons[i] == reasons[j] {
				t.Fatalf("decisions %d and %d share reason %q; the three outcomes must be distinguishable", i, j, reasons[i])
			}
		}
	}
}

// TestEmptyActionRejectedBeforePolicyMatching pins the one invalid action:
// the empty string is an envelope rejection decided before any policy is
// consulted — version 0, no matched policies, the "missing action" reason —
// even when a published allow policy would otherwise grant the request.
// The policy side mirrors this: a policy carrying an empty action cannot be
// published at all, so no published version can ever contain one.
func TestEmptyActionRejectedBeforePolicyMatching(t *testing.T) {
	s := NewStore()
	version, err := s.Publish(actionOrg, 0, []Policy{
		actionPolicy("p-read-allow", "read", EffectAllow),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want version 1", version, err)
	}

	// The same request with the action emptied: denied by the envelope, not
	// by policy evaluation. The published allow cannot be borrowed by an
	// action-less request.
	d := s.Decide(actionOrg, actionRequest(""))
	wantActionDecision(t, d, false, "missing action", nil, 0,
		"empty action is an envelope rejection")

	// The allow really was there to borrow: the identical request carrying
	// the action is allowed. The denial above is caused by the empty action
	// and nothing else.
	allowed := s.Decide(actionOrg, actionRequest("read"))
	wantActionDecision(t, allowed, true, "matched allow policy",
		[]string{"p-read-allow"}, 1, "same request with the action present")

	// The envelope denial is audited like any other decision, preserving the
	// empty action and the version-0 explanation.
	recs, cp, err := s.AuditExport(actionOrg, 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit(actionOrg, recs, cp); err != nil {
		t.Fatalf("chain must verify: %v", err)
	}
	var found bool
	for _, r := range recs {
		if r.Kind == AuditDecision && r.Decision != nil && r.Decision.Request.Action == "" {
			found = true
			if !reflect.DeepEqual(r.Decision.Decision, d) {
				t.Fatalf("empty-action record = %+v, want returned %+v", r.Decision.Decision, d)
			}
		}
	}
	if !found {
		t.Fatal("the empty-action envelope denial was not recorded in the audit chain")
	}

	// A policy with an empty action is rejected at publish and consumes no
	// version, so the empty action can never become a published grant.
	if _, err := s.Publish(actionOrg, 1, []Policy{
		actionPolicy("p-empty-action", "", EffectAllow),
	}); !errors.Is(err, ErrInvalidPolicySet) {
		t.Fatalf("publish empty-action policy err = %v, want ErrInvalidPolicySet", err)
	}
	if got := s.CurrentVersion(actionOrg); got != 1 {
		t.Fatalf("current version = %d, want 1 after rejected publish", got)
	}
}

// TestActionDecisionsSurviveArchiveAndOfflineReview pins the audit and
// offline-review half of the contract. Decisions that differ only in the
// request's action bytes — including the 0xFF/0xFE/U+FFFD triple and the
// empty-action envelope rejection — are exported, archived to bytes and
// read back. The stored records must keep the raw action bytes and the full
// explanation, stay pairwise distinguishable in the material, and the
// offline review of every one must recompute the identical decision from
// the saved action and the recorded policy version, marked consistent.
func TestActionDecisionsSurviveArchiveAndOfflineReview(t *testing.T) {
	actFF, actFE, actFD := rawByteActions()

	s := NewStore()
	version, err := s.Publish(actionOrg, 0, []Policy{
		actionPolicy("p-read-allow", "read", EffectAllow),
		actionPolicy("p-act-ff-allow", actFF, EffectAllow),
		actionPolicy("p-act-fe-deny", actFE, EffectDeny),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want version 1", version, err)
	}

	// Chain layout (seq 1 is the publish): one decision per action, each
	// reaching a different conclusion by action bytes alone, plus the
	// empty-action envelope rejection.
	//	seq 2  "read" allow        seq 3  0xFF action allow
	//	seq 4  0xFE action deny    seq 5  U+FFFD action default deny
	//	seq 6  "" missing action
	online := map[int]Decision{}
	decide := func(seq int, action string) {
		online[seq] = s.Decide(actionOrg, actionRequest(action))
	}
	decide(2, "read")
	decide(3, actFF)
	decide(4, actFE)
	decide(5, actFD)
	decide(6, "")

	wantActionBySeq := map[int]string{2: "read", 3: actFF, 4: actFE, 5: actFD, 6: ""}

	recs, cp, err := s.AuditExport(actionOrg, 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyAudit(actionOrg, recs, cp); err != nil {
		t.Fatalf("chain with raw-byte actions must verify: %v", err)
	}
	if len(recs) != 6 {
		t.Fatalf("exported %d records, want 6 (one publish + five decisions)", len(recs))
	}

	// Every decision record preserves the submitted action byte for byte and
	// the decision actually returned.
	for seq, wantAction := range wantActionBySeq {
		r := recs[seq-1]
		if r.Kind != AuditDecision || r.Decision == nil {
			t.Fatalf("seq %d is not a decision record: %+v", seq, r)
		}
		if r.Decision.Request.Action != wantAction {
			t.Fatalf("seq %d stored action %q, want byte-exact %q", seq, r.Decision.Request.Action, wantAction)
		}
		if !reflect.DeepEqual(r.Decision.Decision, online[seq]) {
			t.Fatalf("seq %d stored decision %+v, want returned %+v", seq, r.Decision.Decision, online[seq])
		}
	}

	// Records that differ only in the action stay distinguishable in the
	// material: the three byte-confusable actions were not saved as one
	// replaced character, and their records' fingerprints differ pairwise.
	fps := map[string]int{}
	for _, seq := range []int{3, 4, 5} {
		fp := recs[seq-1].Fingerprint
		if other, dup := fps[fp]; dup {
			t.Fatalf("seqs %d and %d share fingerprint %s: distinct actions collapsed in the chain", other, seq, fp)
		}
		fps[fp] = seq
	}

	// The full export survives archiving and reading back unchanged.
	archive, err := EncodeAuditArchive(actionOrg, recs, cp)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	if again, err := EncodeAuditArchive(actionOrg, recs, cp); err != nil || !bytes.Equal(again, archive) {
		t.Fatalf("encoding must be deterministic: equal=%v err=%v", bytes.Equal(again, archive), err)
	}
	decoded, err := DecodeAuditArchive(archive, actionOrg, cp)
	if err != nil {
		t.Fatalf("decode: %v", err)
	}
	if !reflect.DeepEqual(decoded, recs) {
		t.Fatalf("decoded records differ from export:\n got %+v\nwant %+v", decoded, recs)
	}
	// The raw action bytes in particular survived the archive byte for byte.
	for seq, wantAction := range wantActionBySeq {
		if got := decoded[seq-1].Decision.Request.Action; got != wantAction {
			t.Fatalf("seq %d action after archive = %q, want byte-exact %q", seq, got, wantAction)
		}
	}

	// Offline review of every decision, run on the decoded material,
	// recomputes the identical allow or deny from the saved action and the
	// recorded policy version, and marks original and recomputed consistent.
	for seq := 2; seq <= 6; seq++ {
		review, err := RecheckDecisionOffline(actionOrg, decoded, cp, seq)
		if err != nil {
			t.Fatalf("offline review seq %d: %v", seq, err)
		}
		if !review.Consistent {
			t.Fatalf("seq %d review inconsistent: original %+v vs recomputed %+v",
				seq, review.Original, review.Recomputed)
		}
		if !reflect.DeepEqual(review.Recomputed, online[seq]) {
			t.Fatalf("seq %d recomputed %+v != online decision %+v", seq, review.Recomputed, online[seq])
		}
		if review.Original.Version != online[seq].Version {
			t.Fatalf("seq %d recorded version %d, want the version decided online %d",
				seq, review.Original.Version, online[seq].Version)
		}
	}
}

